contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single public entry for the property test
    // params: caller address to become admin (adminAddr) and a description string
    // we will simulate two scenarios depending on the boolean makeAdmin:
    // - if makeAdmin is true: we first arrange that adminAddr is an admin by calling c.isAdmin setter is not available publicly, but C exposes mapping isAdmin as public getter only; however we cannot set it externally. Instead we exploit that the test deployer is the owner of the freshly deployed C, but per problem setup c is freshly deployed and isAdmin mapping is initially false for everyone. Therefore to observe both outcomes, we will use two callers: one that is already admin according to c.isAdmin (we can only observe it), and otherwise expect revert. The general rule we assert is: c.newEmergencyOracle succeeds iff c.isAdmin(msg.sender) is true.

    function run(address caller, string calldata description) public payable {
        require(description.length > 0);

        // Observe whether caller is admin before the call
        bool wasAdmin = c.isAdmin(caller);

        // We'll try to call newEmergencyOracle as the provided caller by using low-level call
        // since InvMutTest is the sender for calls to c, we must simulate the call from this contract
        // so we encode the call and perform it; however msg.sender inside c will be this contract,
        // not the `caller` param. The only way to make msg.sender equal to caller is if caller is an EOA that calls run directly,
        // but the checker will call run once; it sets msg.sender = InvMutTest deployer. Given constraints, we instead assert the following general property that relates the public observable isAdmin for msg.sender (which is this contract) to success of the call.

        // Recompute admin status for this contract (the actual caller of c)
        bool selfIsAdmin = c.isAdmin(address(this));

        // Attempt the state-changing call and capture whether it reverted
        bool reverted;
        bytes memory payload = abi.encodeWithSignature("newEmergencyOracle(string)", description);
        (bool ok, ) = address(c).call(payload);
        reverted = !ok;

        // After a successful call, the contract should have created a new EmergencyOracle contract and emitted an event.
        // We cannot read emitted events here, but we can infer success by the fact that the call did not revert, and that the returned new oracle address would not be observable.
        // The general rule: the call reverts exactly when this caller is not an admin according to the public isAdmin getter.
        assert(reverted == (!selfIsAdmin));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // Single public entry containing the property test.
    // We take a description string as input and assert relation between c.isAdmin(this) and whether the call reverts.
    function run(string calldata description) public payable {
        // description may be empty; no precondition required
        // Observe whether this contract is an admin according to the public getter
        bool selfIsAdmin = c.isAdmin(address(this));

        // Prepare payload for the state-changing call
        bytes memory payload = abi.encodeWithSignature("newEmergencyOracle(string)", description);

        // Execute and capture whether it reverted
        (bool ok, ) = address(c).call(payload);
        bool reverted = !ok;

        // General rule: the call reverts exactly when this contract is not an admin as reported by c.isAdmin
        assert(reverted == (!selfIsAdmin));
    }

    receive() external payable {}
}
